R=Path(__file__).resolve().parent;S=Path('/workspace/scratch/TCGA_LIHC_candidate30_survival');V=Path('/workspace/codex/results/PGAM5_RNA_annotation_deconvolution_v4');prev=Path('/workspace/codex/results/TCGA_LIHC_candidate31_survival');p=pd.read_csv(R/'patient_scores.csv');counts=pd.read_csv(R/'selected_patient_reference_gene_counts.csv.gz',index_col=0);cp=pd.read_csv(R/'selected_patient_reference_gene_CP10k.csv.gz',index_col=0);weights=pd.read_csv(R/'all_reference_component_estimates.csv',index_col=0);ridge=pd.read_csv(R/'ridge_sensitivity_component_estimates.csv',index_col=0);prep=json.loads((R/'preparation_summary.json').read_text());stats=pd.read_csv(R/'survival_statistics.csv');rng=np.random.default_rng(20261009);subset=p.iloc[np.sort(rng.choice(len(p),8,replace=False))];recovered={};library=np.zeros(len(subset));featuregenes=set(counts.columns)
